def __getitem__(self, key):
    if isinstance(key, int):
        return self._get_by_index(key)
    elif isinstance(key, slice):
        start_idx, stop_idx, step_idx = key.indices(self._len)
        return numeric_range(
            self._start + start_idx * self._step,
            self._start + stop_idx * self._step,
            self._step * step_idx,
        )
    else:
        raise TypeError(
            'numeric range indices must be '
            f'integers or slices, not {type(key).__name__}'
        )

def test_reversed_is_none(self):
    # See https://github.com/more-itertools/more-itertools/issues/1001
    class ReversedIsNone:
        __reversed__ = None

        def __iter__(self):
            return iter([1])

    self.assertEqual(mi.last(ReversedIsNone()), 1)
